# Check whether fitting one palette cell onto the canvas's 9-background can resolve the one-cell area surplus.
target9={(r,c) for r,row in enumerate(canvas) for c,v in enumerate(row) if v==9}
allow1=target4|target9
p1={}
for name,h,w,n in type_defs:
    ps=[]
    for r in range(25-h+1):
        for c in range(10-w+1):
            cells={(rr,cc) for rr in range(r,r+h) for cc in range(c,c+w)}
            n9=len(cells&target9)
            if cells<=allow1 and n9<=1:
                bits=sum(1<<(rr*10+cc) for rr,cc in cells)
                ps.append((r,c,bits,n9))
    p1[name]=sorted(set(ps))
sol1=[];nodes1=0;counts1={name:n for name,h,w,n in type_defs}
def search1(used,n9,rem,last,chosen):
    global nodes1
    nodes1+=1
    if len(sol1)>=20:return
    if not any(rem.values()):
        if n9==1:sol1.append(chosen.copy())
        return
    choices=[]
    for name,nleft in rem.items():
        if not nleft:continue
        start=last.get(name,-1)+1
        vals=[p for p in p1[name][start:] if not(p[2]&used) and n9+p[3]<=1]
        if not vals:return
        choices.append((len(vals),name,vals))
    _,name,vals=min(choices,key=lambda x:x[0])
    for p in vals:
        idx=p1[name].index(p)
        rem[name]-=1;last[name]=idx;chosen.append((name,p))
        search1(used|p[2],n9+p[3],rem,last,chosen)
        chosen.pop();rem[name]+=1
        if rem[name]==counts1[name]:last.pop(name,None)
        else:
            last[name]=p1[name].index(next(x for nm,x in chosen if nm==name))
        if len(sol1)>=20:break
search1(0,0,counts1.copy(),{},[])
print('nodes',nodes1,'solutions',len(sol1))
for sol in sol1[:3]:print([(name,p[:2],p[3]) for name,p in sol])
